/**
 * WebPraat Web Worker.
 * Encapsulates the Praat C++ WASM runtime, offloading heavy DSP computation
 * and analysis from the UI thread, and exposing a typed API via Comlink.
 */

import * as Comlink from 'comlink';
import type {
  PraatWorkerApi,
  SoundInfo,
  PitchAnalysisParams,
  FormantAnalysisParams,
  SpectrogramAnalysisParams,
} from '../types/wasm';
// @ts-expect-error - praatlib.js is generated by wasm build
import createPraatModule from '../../public/praatlib.js';

let Module: any = null;
let initialized = false;

// Wrapped bridge functions
let praat_bridge_init: () => number;
let praat_bridge_create_sound: (ptr: number, n: number, channels: number, fs: number, name: string) => number;
let praat_bridge_sound_read_from_memory: (ptr: number, length: number, name: string) => number;
let praat_bridge_destroy_object: (id: number) => void;
let praat_bridge_get_object_count: () => number;
let praat_bridge_get_object_name: (id: number) => string;
let praat_bridge_get_object_class: (id: number) => string;
let praat_bridge_sound_get_duration: (id: number) => number;
let praat_bridge_sound_get_sample_rate: (id: number) => number;
let praat_bridge_sound_get_num_samples: (id: number) => number;
let praat_bridge_sound_get_num_channels: (id: number) => number;
let praat_bridge_sound_get_channel_samples: (id: number, channel: number, dest: number, maxSamples: number) => number;
let praat_bridge_sound_save_as_wav_file: (id: number, path: string) => number;
let praat_bridge_sound_to_pitch: (id: number, time_step: number, floor: number, ceiling: number) => number;
let praat_bridge_sound_to_formant: (id: number, time_step: number, n_formants: number, max_freq: number, win_len: number) => number;
let praat_bridge_sound_to_spectrogram: (id: number, win_len: number, max_freq: number, time_step: number, shape: number) => number;
let praat_bridge_pitch_get_mean: (id: number, tmin: number, tmax: number) => number;
let praat_bridge_pitch_get_value_at_time: (id: number, time: number) => number;
let praat_bridge_execute_script: (text: string) => string;
let praat_bridge_get_info_output: () => string;

async function ensureInit(): Promise<boolean> {
  if (initialized && Module) return true;

  Module = await createPraatModule({
    locateFile(path: string, prefix: string) {
      if (path.endsWith('.wasm')) {
        if (typeof window !== 'undefined' || (typeof self !== 'undefined' && 'WorkerGlobalScope' in self)) {
          return '/praatlib.wasm';
        }
        return (prefix || '') + path;
      }
      return (prefix || '') + path;
    },
  });

  praat_bridge_init = Module.cwrap('praat_bridge_init', 'number', []);
  praat_bridge_create_sound = Module.cwrap('praat_bridge_create_sound', 'number', ['number', 'number', 'number', 'number', 'string']);
  praat_bridge_sound_read_from_memory = Module.cwrap('praat_bridge_sound_read_from_memory', 'number', ['number', 'number', 'string']);
  praat_bridge_destroy_object = Module.cwrap('praat_bridge_destroy_object', null, ['number']);
  praat_bridge_get_object_count = Module.cwrap('praat_bridge_get_object_count', 'number', []);
  praat_bridge_get_object_name = Module.cwrap('praat_bridge_get_object_name', 'string', ['number']);
  praat_bridge_get_object_class = Module.cwrap('praat_bridge_get_object_class', 'string', ['number']);
  praat_bridge_sound_get_duration = Module.cwrap('praat_bridge_sound_get_duration', 'number', ['number']);
  praat_bridge_sound_get_sample_rate = Module.cwrap('praat_bridge_sound_get_sample_rate', 'number', ['number']);
  praat_bridge_sound_get_num_samples = Module.cwrap('praat_bridge_sound_get_num_samples', 'number', ['number']);
  praat_bridge_sound_get_num_channels = Module.cwrap('praat_bridge_sound_get_num_channels', 'number', ['number']);
  praat_bridge_sound_get_channel_samples = Module.cwrap('praat_bridge_sound_get_channel_samples', 'number', ['number', 'number', 'number', 'number']);
  praat_bridge_sound_save_as_wav_file = Module.cwrap('praat_bridge_sound_save_as_wav_file', 'number', ['number', 'string']);
  praat_bridge_sound_to_pitch = Module.cwrap('praat_bridge_sound_to_pitch', 'number', ['number', 'number', 'number', 'number']);
  praat_bridge_sound_to_formant = Module.cwrap('praat_bridge_sound_to_formant', 'number', ['number', 'number', 'number', 'number', 'number']);
  praat_bridge_sound_to_spectrogram = Module.cwrap('praat_bridge_sound_to_spectrogram', 'number', ['number', 'number', 'number', 'number', 'number']);
  praat_bridge_pitch_get_mean = Module.cwrap('praat_bridge_pitch_get_mean', 'number', ['number', 'number', 'number']);
  praat_bridge_pitch_get_value_at_time = Module.cwrap('praat_bridge_pitch_get_value_at_time', 'number', ['number', 'number']);
  praat_bridge_execute_script = Module.cwrap('praat_bridge_execute_script', 'string', ['string']);
  praat_bridge_get_info_output = Module.cwrap('praat_bridge_get_info_output', 'string', []);

  const res = praat_bridge_init();
  if (res !== 1) {
    throw new Error('praat_bridge_init failed in worker');
  }

  initialized = true;
  return true;
}

export const praatWorkerApi: PraatWorkerApi = {
  async init(): Promise<boolean> {
    return ensureInit();
  },

  async createSound(samples: Float64Array, n: number, channels: number, fs: number, name: string): Promise<number> {
    await ensureInit();
    const bytes = samples.length * 8;
    const ptr = Module._malloc(bytes);
    try {
      Module.HEAPF64.set(samples, ptr >> 3);
      const soundId = praat_bridge_create_sound(ptr, n, channels, fs, name);
      if (soundId <= 0) throw new Error(`Failed to create Sound object: ${name}`);
      return soundId;
    } finally {
      Module._free(ptr);
    }
  },

  async readSoundFromBuffer(buffer: Uint8Array, name: string): Promise<number> {
    await ensureInit();
    const ptr = Module._malloc(buffer.length);
    try {
      Module.HEAPU8.set(buffer, ptr);
      const soundId = praat_bridge_sound_read_from_memory(ptr, buffer.length, name);
      if (soundId <= 0) throw new Error(`Failed to parse audio data for ${name}`);
      return soundId;
    } finally {
      Module._free(ptr);
    }
  },

  async destroyObject(id: number): Promise<void> {
    await ensureInit();
    praat_bridge_destroy_object(id);
  },

  async getObjectCount(): Promise<number> {
    await ensureInit();
    return praat_bridge_get_object_count();
  },

  async getObjectName(id: number): Promise<string> {
    await ensureInit();
    return praat_bridge_get_object_name(id);
  },

  async getObjectClass(id: number): Promise<string> {
    await ensureInit();
    return praat_bridge_get_object_class(id);
  },

  async getSoundInfo(soundId: number): Promise<SoundInfo> {
    await ensureInit();
    return {
      id: soundId,
      name: praat_bridge_get_object_name(soundId),
      className: praat_bridge_get_object_class(soundId),
      duration: praat_bridge_sound_get_duration(soundId),
      sampleRate: praat_bridge_sound_get_sample_rate(soundId),
      numSamples: praat_bridge_sound_get_num_samples(soundId),
      numChannels: praat_bridge_sound_get_num_channels(soundId),
    };
  },

  async getSoundChannelSamples(soundId: number, channel: number): Promise<Float64Array> {
    await ensureInit();
    const n = praat_bridge_sound_get_num_samples(soundId);
    if (n <= 0) return new Float64Array(0);

    const ptr = Module._malloc(n * 8);
    try {
      const copied = praat_bridge_sound_get_channel_samples(soundId, channel, ptr, n);
      const result = new Float64Array(copied);
      result.set(Module.HEAPF64.subarray(ptr >> 3, (ptr >> 3) + copied));
      return result;
    } finally {
      Module._free(ptr);
    }
  },

  async soundToPitch(soundId: number, params?: PitchAnalysisParams): Promise<number> {
    await ensureInit();
    const timeStep = params?.timeStep ?? 0.0;
    const floor = params?.pitchFloor ?? 75.0;
    const ceiling = params?.pitchCeiling ?? 600.0;
    const pitchId = praat_bridge_sound_to_pitch(soundId, timeStep, floor, ceiling);
    if (pitchId <= 0) throw new Error(`Sound_to_Pitch failed for sound ID ${soundId}`);
    return pitchId;
  },

  async soundToFormant(soundId: number, params?: FormantAnalysisParams): Promise<number> {
    await ensureInit();
    const timeStep = params?.timeStep ?? 0.0;
    const nFormants = params?.nFormants ?? 5;
    const maxFreq = params?.maxFormant ?? 5500.0;
    const winLen = params?.windowLength ?? 0.025;
    const formantId = praat_bridge_sound_to_formant(soundId, timeStep, nFormants, maxFreq, winLen);
    if (formantId <= 0) throw new Error(`Sound_to_Formant failed for sound ID ${soundId}`);
    return formantId;
  },

  async soundToSpectrogram(soundId: number, params?: SpectrogramAnalysisParams): Promise<number> {
    await ensureInit();
    const winLen = params?.windowLength ?? 0.005;
    const maxFreq = params?.maxFreq ?? 5000.0;
    const timeStep = params?.timeStep ?? 0.002;
    const shape = params?.windowShape ?? 0;
    const spectroId = praat_bridge_sound_to_spectrogram(soundId, winLen, maxFreq, timeStep, shape);
    if (spectroId <= 0) throw new Error(`Sound_to_Spectrogram failed for sound ID ${soundId}`);
    return spectroId;
  },

  async pitchGetMean(pitchId: number, tmin?: number, tmax?: number): Promise<number> {
    await ensureInit();
    return praat_bridge_pitch_get_mean(pitchId, tmin ?? 0.0, tmax ?? 0.0);
  },

  async pitchGetValueAtTime(pitchId: number, time: number): Promise<number> {
    await ensureInit();
    return praat_bridge_pitch_get_value_at_time(pitchId, time);
  },

  async exportSoundAsWav(soundId: number): Promise<Uint8Array> {
    await ensureInit();
    const tempPath = `/tmp/export_${soundId}_${Date.now()}.wav`;
    const ok = praat_bridge_sound_save_as_wav_file(soundId, tempPath);
    if (!ok) throw new Error(`Failed to export sound ${soundId} as WAV`);

    try {
      const wavBytes = Module.FS.readFile(tempPath);
      return new Uint8Array(wavBytes.buffer, wavBytes.byteOffset, wavBytes.byteLength);
    } finally {
      try { Module.FS.unlink(tempPath); } catch {}
    }
  },

  async executeScript(scriptText: string): Promise<string> {
    await ensureInit();
    return praat_bridge_execute_script(scriptText);
  },

  async getInfoOutput(): Promise<string> {
    await ensureInit();
    return praat_bridge_get_info_output();
  },
};

// Expose via Comlink in Worker scope
if (typeof self !== 'undefined' && typeof (self as any).postMessage === 'function') {
  Comlink.expose(praatWorkerApi);
}

export default praatWorkerApi;
